PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS clients(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,contact_name TEXT,phone TEXT,email TEXT,address TEXT,vat TEXT,status TEXT DEFAULT 'Lead',relationship_type TEXT,monthly_value REAL DEFAULT 0,project_value REAL DEFAULT 0,start_date TEXT,end_date TEXT,source TEXT,notes TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS leads(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,contact_name TEXT,phone TEXT,email TEXT,source TEXT,service_interest TEXT,stage TEXT DEFAULT 'Nuovo lead',expected_value REAL DEFAULT 0,probability REAL DEFAULT 0,next_contact TEXT,notes TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS services(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,category TEXT,indicative_price REAL DEFAULT 0,internal_cost REAL DEFAULT 0,unit TEXT,description TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS client_services(id INTEGER PRIMARY KEY AUTOINCREMENT,client_id INTEGER NOT NULL,service_id INTEGER,custom_name TEXT,quantity REAL DEFAULT 1,period TEXT DEFAULT 'month',price REAL DEFAULT 0,notes TEXT,FOREIGN KEY(client_id) REFERENCES clients(id) ON DELETE CASCADE,FOREIGN KEY(service_id) REFERENCES services(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS projects(id INTEGER PRIMARY KEY AUTOINCREMENT,client_id INTEGER,title TEXT NOT NULL,type TEXT,status TEXT,value REAL DEFAULT 0,cost REAL DEFAULT 0,start_date TEXT,deadline TEXT,notes TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(client_id) REFERENCES clients(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS tasks(id INTEGER PRIMARY KEY AUTOINCREMENT,client_id INTEGER,title TEXT NOT NULL,type TEXT,status TEXT DEFAULT 'Da fare',priority TEXT DEFAULT 'Media',due_date TEXT,notes TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(client_id) REFERENCES clients(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS content(id INTEGER PRIMARY KEY AUTOINCREMENT,client_id INTEGER,week INTEGER,day TEXT,date TEXT,type TEXT,status TEXT DEFAULT 'Idea',objective TEXT,channel TEXT,title TEXT,description TEXT,cta TEXT,published_url TEXT,notes TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(client_id) REFERENCES clients(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS ads(id INTEGER PRIMARY KEY AUTOINCREMENT,client_id INTEGER,campaign TEXT,platform TEXT,period TEXT,budget REAL DEFAULT 0,spend REAL DEFAULT 0,impressions INTEGER DEFAULT 0,reach INTEGER DEFAULT 0,clicks INTEGER DEFAULT 0,messages INTEGER DEFAULT 0,leads INTEGER DEFAULT 0,sales INTEGER DEFAULT 0,revenue REAL DEFAULT 0,notes TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(client_id) REFERENCES clients(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS websites(id INTEGER PRIMARY KEY AUTOINCREMENT,client_id INTEGER,name TEXT,domain TEXT,url TEXT,domain_provider TEXT,hosting_provider TEXT,domain_renewal TEXT,hosting_renewal TEXT,domain_cost REAL DEFAULT 0,hosting_cost REAL DEFAULT 0,github_repo TEXT,cloudflare_project TEXT,status TEXT,notes TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(client_id) REFERENCES clients(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS quotes(id INTEGER PRIMARY KEY AUTOINCREMENT,client_id INTEGER,issue_date TEXT,title TEXT,status TEXT DEFAULT 'Bozza',valid_until TEXT,introduction TEXT,objectives TEXT,strategy TEXT,items_json TEXT,total REAL DEFAULT 0,duration TEXT,payment_terms TEXT,conditions TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(client_id) REFERENCES clients(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS contracts(id INTEGER PRIMARY KEY AUTOINCREMENT,client_id INTEGER,title TEXT,type TEXT,status TEXT DEFAULT 'Bozza',value REAL DEFAULT 0,start_date TEXT,end_date TEXT,payment_terms TEXT,body TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(client_id) REFERENCES clients(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS invoices(id INTEGER PRIMARY KEY AUTOINCREMENT,client_id INTEGER,number TEXT,issue_date TEXT,due_date TEXT,subtotal REAL DEFAULT 0,vat_rate REAL DEFAULT 0,total REAL DEFAULT 0,status TEXT DEFAULT 'In attesa',payment_date TEXT,payment_method TEXT,notes TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(client_id) REFERENCES clients(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS payments(id INTEGER PRIMARY KEY AUTOINCREMENT,client_id INTEGER,type TEXT,amount REAL DEFAULT 0,due_date TEXT,paid_date TEXT,status TEXT DEFAULT 'Da pagare',method TEXT,reference TEXT,notes TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(client_id) REFERENCES clients(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS transactions(id INTEGER PRIMARY KEY AUTOINCREMENT,direction TEXT NOT NULL,date TEXT NOT NULL,category TEXT,amount REAL DEFAULT 0,description TEXT,notes TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS subscriptions(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,category TEXT,amount REAL DEFAULT 0,frequency TEXT,renewal_date TEXT,status TEXT DEFAULT 'Attivo',notes TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS equipment(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,category TEXT,purchase_cost REAL DEFAULT 0,purchase_date TEXT,warranty_end TEXT,serial TEXT,status TEXT DEFAULT 'Operativo',notes TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS reports(id INTEGER PRIMARY KEY AUTOINCREMENT,client_id INTEGER,title TEXT,period TEXT,followers INTEGER DEFAULT 0,reach INTEGER DEFAULT 0,views INTEGER DEFAULT 0,interactions INTEGER DEFAULT 0,contents INTEGER DEFAULT 0,ad_spend REAL DEFAULT 0,leads INTEGER DEFAULT 0,cpl REAL DEFAULT 0,worked TEXT,wins TEXT,improve TEXT,next_strategy TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(client_id) REFERENCES clients(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS documents(id INTEGER PRIMARY KEY AUTOINCREMENT,client_id INTEGER,name TEXT NOT NULL,category TEXT,storage_key TEXT NOT NULL,created_date TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(client_id) REFERENCES clients(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT);
CREATE INDEX IF NOT EXISTS idx_content_date ON content(date);CREATE INDEX IF NOT EXISTS idx_tasks_due ON tasks(due_date);CREATE INDEX IF NOT EXISTS idx_payments_due ON payments(due_date);CREATE INDEX IF NOT EXISTS idx_contracts_end ON contracts(end_date);CREATE INDEX IF NOT EXISTS idx_client_services_client ON client_services(client_id);
